INSERT INTO public.posts (author_id, title, slug, excerpt, content, category, location, cover_image_url, tags, published, published_at) VALUES
('b4efba95-83d2-426c-b2d6-f16798d5bac2', 'Night market math in Taipei', 'night-market-math-taipei', 'Eating our way down one street, and why the kids remember the stall owners more than the food.', '<p>We landed jet-lagged and went straight to the night market, which is either terrible parenting or the best possible introduction to a city.</p><h2>Let the kids order</h2><p>They pointed, we paid, everyone ate something they could not name. It became the rule for the rest of the trip.</p><blockquote>The best travel days are the ones we did not plan past dinner.</blockquote><p>Ten days later, what stuck was not the itinerary. It was the woman at the scallion pancake stall who waved at my son every single night.</p>', 'travel', 'Taipei, Taiwan', '/img/posts/taipei-cover.jpg', ARRAY['Family trip','Food & wandering'], true, '2026-08-16 01:00:00+00'),
('b4efba95-83d2-426c-b2d6-f16798d5bac2', 'The projects I quit, and the one I did not', 'projects-i-quit', 'A short accounting of abandoned side projects, and what the survivor had that the rest did not.', '<p>I have started more things than I have finished. That is not humility, it is a spreadsheet.</p><h2>What actually predicted survival</h2><p>Not market size, not technical difficulty. It was whether I still wanted to use the thing on a Tuesday night when nobody was watching.</p><p>Everything else was enthusiasm wearing a business plan.</p>', 'writing', NULL, '/img/posts/side-projects-cover.jpg', ARRAY['Building','Side projects'], true, '2026-08-17 01:00:00+00');